const original = $('Loop por canal1').item.json;
const response = $json || {};
const errorObj = response.error ?? response;
let errorText = '';
try { errorText = typeof errorObj === 'string' ? errorObj : JSON.stringify(errorObj); }
catch { errorText = String(errorObj); }
errorText = errorText.slice(0, 1500);
if (!errorText || errorText === '{}') errorText = 'Falha ao criar o contêiner de mídia no Instagram.';
return [{
  json: {
    ...original,
    Canal: 'instagram',
    success: false,
    media_id: '',
    published_url: '',
    error_text: errorText
  }
}];

// Somente configuração não secreta. Tokens permanecem nas credenciais do n8n.
return [{ json: {
  META_GRAPH_VERSION: 'v26.0',
  IG_USER_ID: '17841446264766146',
  FB_PAGE_ID: '492773484524523',
  SPREADSHEET_ID: '1ytO0uRH8ImzUL8wgedPjtEKZfJBIVxhai-VU0nhGhtE',
  CALENDAR_SHEET: 'Calendário Meta',
  LOG_SHEET: 'Meta - Log de publicações',
  CONFIG_SHEET: 'Automação Meta',
  WORKFLOW: 'CBN META 03 — PUBLICADOR META — V2 PRODUÇÃO',
  MAX_POSTS_PER_EXECUTION: 1
} }];

const config = $('Validar configuração fail-closed').first().json;
const rows = $items('Ler Calendário Meta — SOMENTE LEITURA1').map(item => item.json || {});
const logs = $input.all().map(item => item.json || {});
const norm = value => String(value ?? '').trim();
const upper = value => norm(value).toUpperCase();
const asInt = value => /^\d+$/.test(norm(value)) ? Number(value) : 0;
const now = new Date();

const parseScheduled = (dateValue, timeValue) => {
  const dateMatch = norm(dateValue).match(/^(\d{1,2})[\/-](\d{1,2})[\/-](\d{4})$/);
  const timeMatch = norm(timeValue).match(/^(\d{1,2}):(\d{2})(?::\d{2})?$/);
  if (!dateMatch || !timeMatch) return null;
  const [, day, month, year] = dateMatch;
  const [, hour, minute] = timeMatch;
  const iso = year + '-' + month.padStart(2, '0') + '-' + day.padStart(2, '0') + 'T' + hour.padStart(2, '0') + ':' + minute + ':00-03:00';
  const parsed = new Date(iso);
  if (Number.isNaN(parsed.getTime())) return null;
  const formatter = new Intl.DateTimeFormat('en-CA', { timeZone: config.TIMEZONE, year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' });
  const parts = Object.fromEntries(formatter.formatToParts(parsed).filter(part => part.type !== 'literal').map(part => [part.type, part.value]));
  if (parts.year !== year || parts.month !== month.padStart(2, '0') || parts.day !== day.padStart(2, '0') || parts.hour !== hour.padStart(2, '0') || parts.minute !== minute) return null;
  return parsed;
};

const latestByComposite = new Map();
for (const log of logs) {
  const key = norm(log['Publish Key']);
  const channel = upper(log.Canal);
  const status = upper(log.Status);
  if (!key || !['INSTAGRAM', 'FACEBOOK'].includes(channel)) continue;
  if (upper(key).includes('{ $JSON') || key.includes('{{') || channel.includes('{{')) continue;
  if (!['RESERVADO', 'PUBLICANDO', 'PUBLICADO', 'ERRO'].includes(status)) continue;
  latestByComposite.set(key + ':' + channel, log);
}

const candidates = [];
for (const row of rows) {
  const postId = norm(row.post_id);
  if (!postId || upper(row.Aprovação) !== 'APROVADO') continue;
  if (!['APROVADO_PUBLICAR', 'PARCIAL', 'ERRO'].includes(upper(row.Status))) continue;
  if (upper(row.Formato) !== 'POST ESTÁTICO') continue;
  if (upper(row.Status) === 'PUBLICANDO' || norm(row.locked_at)) continue;

  const scheduledAt = parseScheduled(row.Data, row.Horário);
  if (!scheduledAt || scheduledAt.getTime() > now.getTime()) continue;

  let urls = [];
  const rawJson = norm(row.media_urls_json);
  if (rawJson) {
    try { const parsed = JSON.parse(rawJson); urls = Array.isArray(parsed) ? parsed : []; }
    catch { continue; }
  } else if (norm(row['Arquivo / URL da mídia'])) {
    urls = [norm(row['Arquivo / URL da mídia'])];
  }
  urls = urls.map(norm).filter(Boolean);
  if (urls.length !== 1 || !String(urls[0]).toLowerCase().startsWith('https://')) continue;
  const caption = norm(row['Legenda / roteiro-base']);
  if (!caption) continue;

  const publishKey = norm(row.publish_key) || (postId + ':' + norm(row.Data) + ':' + norm(row.Horário) + ':STATIC_V2');
  const channels = [];
  const attemptsByChannel = {};

  const inspectChannel = (channel, enabledField, statusField, idField, attemptsField, nextRetryField) => {
    if (upper(row[enabledField]) !== 'SIM') return;
    const channelUpper = channel.toUpperCase();
    const latest = latestByComposite.get(publishKey + ':' + channelUpper);
    const latestStatus = upper(latest?.Status);
    const alreadyPublished = upper(row[statusField]) === 'PUBLICADO' || Boolean(norm(row[idField])) || latestStatus === 'PUBLICADO';
    if (alreadyPublished) return;
    if (['PUBLICANDO'].includes(upper(row[statusField])) || ['RESERVADO', 'PUBLICANDO'].includes(latestStatus)) return;
    const attempts = asInt(row[attemptsField]);
    if (attempts >= Number(config.MAX_ATTEMPTS_CANAL)) return;
    const nextRetry = norm(row[nextRetryField]);
    if (nextRetry) {
      const retryAt = new Date(nextRetry);
      if (Number.isNaN(retryAt.getTime()) || retryAt.getTime() > now.getTime()) return;
    }
    channels.push(channel);
    attemptsByChannel[channel] = attempts + 1;
  };

  inspectChannel('instagram', 'Instagram', 'instagram_status', 'ID Instagram', 'instagram_attempts', 'instagram_next_retry_at');
  inspectChannel('facebook', 'Facebook', 'facebook_status', 'ID Facebook', 'facebook_attempts', 'facebook_next_retry_at');
  if (!channels.length) continue;

  candidates.push({ json: {
    ...row,
    post_id: postId,
    publish_key: publishKey,
    media_url: urls[0],
    caption,
    channels,
    attempts_by_channel: attemptsByChannel,
    row_version_before: asInt(row.row_version),
    scheduled_at: scheduledAt.toISOString(),
    meta_graph_version: config.META_GRAPH_VERSION,
    ig_user_id: config.IG_USER_ID,
    fb_page_id: config.FB_PAGE_ID,
    workflow: config.WORKFLOW,
    max_attempts_channel: config.MAX_ATTEMPTS_CANAL,
    retry_1_minutes: config.RETRY_1_MINUTES,
    retry_2_minutes: config.RETRY_2_MINUTES
  } });
  if (candidates.length >= Number(config.MAX_POSTS_PER_EXECUTION || 1)) break;
}
return candidates;

const post = $json;
const igSelected = (post.channels || []).includes('instagram');
const fbSelected = (post.channels || []).includes('facebook');
const igAttempts = igSelected ? Number(post.attempts_by_channel.instagram) : Number(post.instagram_attempts || 0);
const fbAttempts = fbSelected ? Number(post.attempts_by_channel.facebook) : Number(post.facebook_attempts || 0);
return [{ json: {
  ...post,
  Status: 'PUBLICANDO',
  attempts: String(Math.max(igAttempts, fbAttempts)),
  locked_at: new Date().toISOString(),
  last_error_json: '',
  row_version: String(Number(post.row_version_before || 0) + 1),
  instagram_status: igSelected ? 'PUBLICANDO' : String(post.instagram_status || ''),
  facebook_status: fbSelected ? 'PUBLICANDO' : String(post.facebook_status || ''),
  instagram_attempts: String(igAttempts),
  facebook_attempts: String(fbAttempts)
} }];

const post = $json;
return (post.channels || []).map(Canal => ({ json: {
  ...post,
  Canal,
  channel_attempt: Number(post.attempts_by_channel?.[Canal] || 0)
} }));

const original = $('Loop por canal1').item.json;
const publishResponse = $('Instagram — publicar contêiner1').item.json || {};
const permalinkResponse = $json || {};
const mediaId = String(publishResponse.id ?? publishResponse.media_id ?? '').trim();
let errorText = '';
if (!mediaId) {
  const errorObj = publishResponse.error ?? publishResponse;
  try { errorText = typeof errorObj === 'string' ? errorObj : JSON.stringify(errorObj); }
  catch { errorText = String(errorObj); }
  if (!errorText || errorText === '{}') errorText = 'A Meta não retornou ID da mídia publicada.';
}
return [{ json: {
  ...original,
  Canal: 'instagram',
  success: Boolean(mediaId),
  media_id: mediaId,
  published_url: mediaId ? String(permalinkResponse.permalink || original.instagram_url || '') : '',
  error_text: errorText.slice(0, 1500)
} }];

const original = $('Loop por canal1').item.json;
const response = $json || {};
const mediaId = String(response.post_id ?? response.id ?? '').trim();
const errorObj = response.error ?? response;
let errorText = '';
if (!mediaId) {
  try { errorText = typeof errorObj === 'string' ? errorObj : JSON.stringify(errorObj); }
  catch { errorText = String(errorObj); }
  errorText = errorText.slice(0, 1500);
  if (!errorText || errorText === '{}') errorText = 'A Meta não retornou ID da publicação no Facebook.';
}
return [{
  json: {
    ...original,
    Canal: 'facebook',
    success: Boolean(mediaId),
    media_id: mediaId,
    published_url: mediaId ? `https://www.facebook.com/${mediaId}` : '',
    error_text: errorText
  }
}];

const post = $('Selecionar 1 post estático seguro1').first().json;
const executionId = String($execution.id);
const logs = $input.all().map(item => item.json || {});
const norm = value => String(value ?? '').trim();
const upper = value => norm(value).toUpperCase();
const required = new Set(post.channels || []);
const now = new Date();

const findFinal = channel => {
  const matches = logs.filter(log =>
    norm(log['Execução']) === executionId &&
    norm(log['Post ID']) === norm(post.post_id) &&
    norm(log['Publish Key']) === norm(post.publish_key) &&
    upper(log.Canal) === channel.toUpperCase() &&
    ['PUBLICADO', 'ERRO'].includes(upper(log.Status))
  );
  return matches.at(-1) || null;
};

const result = {};
for (const channel of ['instagram', 'facebook']) {
  const requested = upper(post[channel === 'instagram' ? 'Instagram' : 'Facebook']) === 'SIM';
  const statusField = channel + '_status';
  const idField = channel === 'instagram' ? 'ID Instagram' : 'ID Facebook';
  const currentPublished = upper(post[statusField]) === 'PUBLICADO' || Boolean(norm(post[idField]));
  const executionLog = required.has(channel) ? findFinal(channel) : null;
  const published = currentPublished || upper(executionLog?.Status) === 'PUBLICADO';
  const failed = required.has(channel) && !published;
  const attempt = required.has(channel) ? Number(post.attempts_by_channel?.[channel] || 0) : Number(post[channel + '_attempts'] || 0);
  let nextRetry = '';
  if (failed && attempt < Number(post.max_attempts_channel || 3)) {
    const minutes = attempt === 1 ? Number(post.retry_1_minutes || 10) : Number(post.retry_2_minutes || 30);
    nextRetry = new Date(now.getTime() + minutes * 60000).toISOString();
  }
  result[channel] = {
    requested,
    status: published ? 'PUBLICADO' : (failed ? 'ERRO' : (norm(post[statusField]) || 'PENDENTE')),
    id: norm(executionLog?.['Media ID']) || norm(post[idField]),
    url: norm(executionLog?.URL) || norm(post[channel + '_url']),
    attempts: attempt,
    error: failed ? (norm(executionLog?.Erro) || 'Resultado final não localizado no log desta execução.').slice(0, 1500) : '',
    nextRetry
  };
}

const requested = Object.values(result).filter(channel => channel.requested);
const publishedCount = requested.filter(channel => channel.status === 'PUBLICADO').length;
const failedCount = requested.filter(channel => channel.status === 'ERRO').length;
const generalStatus = requested.length > 0 && publishedCount === requested.length
  ? 'PUBLICADO'
  : publishedCount > 0
    ? 'PARCIAL'
    : failedCount > 0
      ? 'ERRO'
      : 'APROVADO_PUBLICAR';
const errors = Object.fromEntries(Object.entries(result).filter(([, value]) => value.error).map(([key, value]) => [key, value.error]));

return [{ json: {
  post_id: post.post_id,
  Status: generalStatus,
  publish_key: post.publish_key,
  attempts: String(Math.max(result.instagram.attempts, result.facebook.attempts)),
  locked_at: '',
  last_error_json: Object.keys(errors).length ? JSON.stringify(errors).slice(0, 1500) : '',
  row_version: String(Number(post.row_version_before || 0) + 2),
  instagram_status: result.instagram.status,
  facebook_status: result.facebook.status,
  'ID Instagram': result.instagram.id,
  'ID Facebook': result.facebook.id,
  'Horário publicado': generalStatus === 'PUBLICADO' ? now.toISOString() : String(post['Horário publicado'] || ''),
  Erro: Object.values(errors).join(' | ').slice(0, 1500),
  instagram_url: result.instagram.url,
  facebook_url: result.facebook.url,
  instagram_attempts: String(result.instagram.attempts),
  facebook_attempts: String(result.facebook.attempts),
  instagram_last_error_json: result.instagram.error,
  facebook_last_error_json: result.facebook.error,
  instagram_next_retry_at: result.instagram.nextRetry,
  facebook_next_retry_at: result.facebook.nextRetry
} }];

const config = $json || {};
if (config.PAUSA_GERAL !== 'NAO' || config.PUBLICACAO_LIBERADA !== true) throw new Error('FAIL_CLOSED: publicação não liberada.');
if (!/^v\d+\.\d+$/.test(String(config.META_GRAPH_VERSION || '').trim())) throw new Error('META_GRAPH_VERSION inválida.');
for (const field of ['IG_USER_ID', 'FB_PAGE_ID']) {
  if (!/^\d+$/.test(String(config[field] || '').trim())) throw new Error('Configuração ausente ou inválida: ' + field);
}
return [{ json: config }];

const response = $json || {};
const raw = response.error?.message || response.message || response.description || '';
let detail = String(raw || '').trim();
if (!detail) { try { detail = JSON.stringify(response); } catch { detail = String(response); } }
detail = detail.slice(0, 800);
throw new Error('Falha no preflight da Meta: o Page Access Token nao foi aceito para a Pagina configurada. ' + detail + ' Revise a credencial Header Auth: Name=Authorization; Value=Bearer + espaco + token completo da Pagina CBN, sem aspas, igual, quebras ou valor mascarado. Nenhuma tentativa de publicacao foi consumida.');

const base = $('Configuração central — SEM SEGREDOS1').first().json || {};
const rows = $input.all().map(item => item.json || {});
if (!rows.length) throw new Error('FAIL_CLOSED: aba Automação Meta vazia ou ilegível.');

const canonical = value => String(value ?? '').trim().normalize('NFD').replace(/[\u0300-\u036f]/g, '').toUpperCase().replace(/[^A-Z0-9]+/g, '_').replace(/^_|_$/g, '');
const required = new Set(['PAUSA_GERAL', 'MAX_ATTEMPTS_CANAL', 'RETRY_1_MINUTES', 'RETRY_2_MINUTES', 'TIMEZONE']);
const found = {};

for (const row of rows) {
  const entries = Object.entries(row);
  for (const [header, value] of entries) {
    const key = canonical(header);
    if (required.has(key) && String(value ?? '').trim()) found[key] = String(value).trim();
  }

  const keyEntry = entries.find(([header]) => ['CHAVE', 'CONFIGURACAO', 'PARAMETRO', 'NOME', 'VARIAVEL'].includes(canonical(header)));
  const valueEntry = entries.find(([header]) => ['VALOR', 'VALUE'].includes(canonical(header)));
  if (keyEntry && valueEntry && required.has(canonical(keyEntry[1]))) {
    found[canonical(keyEntry[1])] = String(valueEntry[1] ?? '').trim();
  }

  const values = entries.map(([, value]) => value);
  for (let index = 0; index < values.length - 1; index += 1) {
    const key = canonical(values[index]);
    if (required.has(key) && String(values[index + 1] ?? '').trim()) found[key] = String(values[index + 1]).trim();
  }
}

for (const key of required) {
  if (!found[key]) throw new Error('FAIL_CLOSED: configuração obrigatória ausente em Automação Meta: ' + key);
}

const pause = canonical(found.PAUSA_GERAL);
if (!['SIM', 'NAO'].includes(pause)) throw new Error('FAIL_CLOSED: PAUSA_GERAL deve ser SIM ou NAO.');
const maxAttempts = Number(found.MAX_ATTEMPTS_CANAL);
const retry1 = Number(found.RETRY_1_MINUTES);
const retry2 = Number(found.RETRY_2_MINUTES);
if (maxAttempts !== 3) throw new Error('FAIL_CLOSED: MAX_ATTEMPTS_CANAL deve ser 3 na V2.');
if (retry1 !== 10 || retry2 !== 30) throw new Error('FAIL_CLOSED: retries da V2 devem ser 10 e 30 minutos.');
if (found.TIMEZONE !== 'America/Sao_Paulo') throw new Error('FAIL_CLOSED: TIMEZONE deve ser America/Sao_Paulo.');

return [{ json: {
  ...base,
  PAUSA_GERAL: pause,
  MAX_ATTEMPTS_CANAL: maxAttempts,
  RETRY_1_MINUTES: retry1,
  RETRY_2_MINUTES: retry2,
  TIMEZONE: found.TIMEZONE,
  PUBLICACAO_LIBERADA: pause === 'NAO'
} }];
